def clean_tags(raw_tags):
    cleaned = []
    for raw in raw_tags:
        tag = raw.strip().lower()
        if tag != "":
            cleaned.append(tag)
    return cleaned

if __name__ == "__main__":
    assert clean_tags(["  Data  ", "ML", ""]) == ["data", "ml"]
    assert clean_tags(["   ", "\t"]) == []
    print("behavior preserved")
